#include <map>
#include <iostream>

int main() {
    std::map<int, int> coll = {{1, 10}, {2, 20}, {3, 30}};

    // SAFE C++11+ ITERATION AND ERASURE
    for (auto pos = coll.begin(); pos != coll.end(); ) {
        if (pos->second == 20) { // Condition to erase
            // Assign the iterator to the next valid element
            pos = coll.erase(pos); 
        } else {
            ++pos; // Manual increment only if no erasure occurred
        }
    }

    // Output: {1: 10}, {3: 30}
}
